    p.set_prop(PropKey::from_str("pid"), Value::Num(std::process::id() as f64), WEC);
    p.set_prop(PropKey::from_str("ppid"), Value::Num(parent_pid() as f64), WEC);
    let arch = match std::env::consts::ARCH {
        "aarch64" => "arm64",
        "x86_64" => "x64",
        "x86" => "ia32",
