        for (name, want) in expected {
            let data = std::fs::read(dir.join(name)).unwrap();
            let got = match name.rsplit('.').next().unwrap() {
                "gz" => gzip_decode(&data),
                "zz" => zlib_decode(&data, None),
                "raw" => inflate_raw(&data, None),
                "br" => brotli_decode(&data),
