        }
        let r = self.run_frame(&mut frame);
        self.depth -= 1;
        match r {
            Ok(Completion::Yield(v)) => {
                self.set_gen_state(gen, GenState::SuspendedYield, Some(frame));
                Ok(self.iter_result(v, false))
            }
            Ok(Completion::YieldRaw(v)) => {
