                RSA_PKCS1_PSS_PADDING => rsa::rsa_pss_sign(k, alg, data, opts.salt_length.unwrap_or(rsa::PSS_SALTLEN_DIGEST)),
                p => Err(CryptoError::error(format!("crypto.sign: RSA padding {} is not supported in lumen", p))),
            }
