        AsymKey::EcPrivate { d, .. } => {
            let enc = p1363(opts)?;
            p256::ecdsa_sign(d, alg.unwrap(), data, enc)
        }
        AsymKey::Ed25519Private { seed, .. } => Ok(curve25519::ed25519_sign(seed, data).to_vec()),
        _ => Err(CryptoError::type_error("crypto: cannot create a private key from a public key")),
    }
}

