pub fn parse_pkcs1_public(der: &[u8]) -> Result<AsymKey, CryptoError> {
    let seq = asn1::read_tlv(der, 0)?;
    if seq.tag != asn1::TAG_SEQUENCE {
        return Err(asn1::malformed());
